"""Dynamic LexBFS ordering.

Maintains a valid LexBFS ordering under edge insertions and deletions.

On each update we verify the maintained ordering against the (LB) 4-point
property of Corneil and Krueger:

    for all a < b < c with ac in E and ab not in E,
    there exists d < a with db in E and dc not in E.

If the property still holds, the ordering is a valid LexBFS and we keep it
(cheap path). Otherwise we recompute a fresh LexBFS ordering with the
partition-refinement algorithm of Habib, McConnell, Paul and Viennot
(O(n^2) on the adjacency matrix).
"""


def _lexbfs(g):
    """Static partition-refinement LexBFS on adjacency matrix g.

    Returns a list of all n vertices in a valid LexBFS order.
    """
    n = len(g)
    if n == 0:
        return []
    # buckets: list of lists of vertices; all vertices in a bucket share
    # the same label.  labels[v] is the shared label of v's bucket.
    buckets = [list(range(n))]
    labels = {v: [(0, v)] for v in range(n)}
    order = []
    while buckets:
        # take the first bucket, pick its first vertex
        b = buckets[0]
        v = b[0]
        order.append(v)
        b.pop(0)
        if not b:
            buckets.pop(0)
        pos = len(order)
        # reset: every remaining vertex gets a fresh label starting with
        # (pos, v); neighbors of v get the marker repeated.
        new_buckets = []
        for bucket in buckets:
            non_nb = []
            nb = []
            for w in bucket:
                if g[v][w]:
                    labels[w] = [(pos, v), (pos, v)]
                    nb.append(w)
                else:
                    labels[w] = [(pos, v)]
                    non_nb.append(w)
            if nb:
                new_buckets.append(nb)
            if non_nb:
                new_buckets.append(non_nb)
        buckets = new_buckets
    return order


def _is_lexbfs(g, order):
    """Check the (LB) 4-point property for `order` on graph g. O(n^3).

    For all a<b<c with ac in E and ab not in E, there must exist d<a with
    db in E and dc not in E.
    """
    n = len(order)
    for i in range(n):
        a = order[i]
        for j in range(i + 1, n):
            b = order[j]
            if g[a][b]:
                continue  # need ab not in E
            for k in range(j + 1, n):
                c = order[k]
                if not g[a][c]:
                    continue  # need ac in E
                found = False
                for t in range(i):
                    d = order[t]
                    if g[d][b] and not g[d][c]:
                        found = True
                        break
                if not found:
                    return False
    return True


def init(graph):
    order = _lexbfs(graph)
    return {'ordering': order}


def insert_edge(graph, edge, state):
    # Always recompute: an insertion can create new 4-point obligations
    # (new edge ac with a<b<c, ab not in E) that the old ordering may not
    # satisfy. The 4-point check is O(n^3) and the recompute is O(n^2), so
    # recomputing is the cheaper and simpler option.
    return {'ordering': _lexbfs(graph)}


def delete_edge(graph, edge, state):
    # A deletion can only destroy witnesses, so the property can only be
    # hurt. Verify the (LB) property; recompute if it fails.
    order = state['ordering']
    if _is_lexbfs(graph, order):
        return state
    return {'ordering': _lexbfs(graph)}

"""Dynamic LexBFS ordering.

Strategy: maintain a valid LexBFS ordering. On each update, try to repair
the existing ordering locally (cheap); if repair fails, fall back to a
full O(n^2) partition-refinement LexBFS recompute (always correct).

Validity is certified by the (LB) 4-point property of Corneil and Krueger:
  for all positions a < b < c with ac in E and ab not in E,
  there exists d < a with db in E and dc not in E.
"""


def _check_valid(graph, order):
    """Check the LB 4-point property for `order` on `graph`. O(n^3)."""
    n = len(order)
    pos = [0] * n
    for i, v in enumerate(order):
        pos[v] = i
    adj = [set() for _ in range(n)]
    for v in range(n):
        row = graph[v]
        for w in range(v + 1, n):
            if row[w]:
                adj[v].add(w)
                adj[w].add(v)
    for b in range(n):
        pb = pos[b]
        for c in range(n):
            if c == b:
                continue
            pc = pos[c]
            if pc <= pb:
                continue
            if b in adj[c]:
                continue  # need ab not in E
            # m = min pos[d] over d in adj[b] \ adj[c]
            m = None
            for d in adj[b]:
                if d not in adj[c]:
                    pd = pos[d]
                    if m is None or pd < m:
                        m = pd
            # m_a = min pos[a] over a in adj[c] with pos[a] < pb
            m_a = None
            for a in adj[c]:
                pa = pos[a]
                if pa < pb:
                    if m_a is None or pa < m_a:
                        m_a = pa
            if m_a is not None and m is not None and m_a <= m:
                return False
    return True


def _lexbfs_full(graph):
    """Full O(n^2) LexBFS via partition refinement. Returns ordering list."""
    n = len(graph)
    if n == 0:
        return []
    adj = [set() for _ in range(n)]
    for v in range(n):
        row = graph[v]
        for w in range(v + 1, n):
            if row[w]:
                adj[v].add(w)
                adj[w].add(v)

    # Bucket-based LexBFS.
    # buckets: list of lists of vertices, in lexicographic label order.
    # Initially one bucket with all vertices.
    # At each step: pick first vertex of first non-empty bucket, refine all buckets.
    # After refinement by vertex v: for each bucket in order, the neighbor
    # part (_1) comes before the non-neighbor part (_0), and buckets maintain
    # their relative order.
    buckets = [list(range(n))]
    order = []

    for _ in range(n):
        # Find first non-empty bucket
        first_idx = None
        for i, b in enumerate(buckets):
            if b:
                first_idx = i
                break
        if first_idx is None:
            break
        v = buckets[first_idx][0]
        buckets[first_idx] = buckets[first_idx][1:]
        order.append(v)
        # Refine all buckets by v
        new_buckets = []
        for b in buckets:
            if not b:
                continue
            b1 = [x for x in b if x in adj[v]]
            b0 = [x for x in b if x not in adj[v]]
            if b1:
                new_buckets.append(b1)
            if b0:
                new_buckets.append(b0)
        buckets = new_buckets
    return order


def _try_repair_insert(graph, order, u, v):
    """Try to repair ordering after inserting edge (u,v). Returns new order or None."""
    n = len(order)
    pos = {vertex: i for i, vertex in enumerate(order)}
    pu, pv = pos[u], pos[v]
    if abs(pu - pv) == 1:
        return order
    # Try moving v to be just before u
    new_order = order[:pu] + [v] + order[pu:pv] + order[pv + 1:]
    if _check_valid(graph, new_order):
        return new_order
    # Try moving v to be just after u
    new_order = order[:pu + 1] + [v] + order[pu + 1:pv] + order[pv + 1:]
    if _check_valid(graph, new_order):
        return new_order
