    """Check the (LB) 4-point property. Returns True if valid. O(n^4)."""
    n = len(order)
    for a in range(n):
        va = order[a]
        for b in range(a + 1, n):
            vb = order[b]
            if graph[va][vb]:
                continue
            for c in range(b + 1, n):
                vc = order[c]
                if not graph[va][vc]:
                    continue
                found = False
                for d in range(a):
                    vd = order[d]
                    if graph[vd][vb] and not graph[vd][vc]:
                        found = True
                        break
                if not found:
                    return False
    return True


